//! Checks the pure-Rust SVS reader against pixels QuPath itself decoded.
//!
//! Fixture generated by `parity/java/SlideRegion.java` via
//! `./parity/record-slide.sh`, which reads through QuPath's Bio-Formats
//! server — the same path a real QuPath detection run uses.
//!
//! This is the parity test that matters most in the repository. A wrong kernel
//! shape or a wrong queue ordering produces output that is visibly wrong; a
//! wrong JPEG colour conversion produces output that looks like a perfectly
//! plausible slide and is quietly biased, and every measurement computed
//! downstream would inherit that bias while still agreeing with itself.
//!
//! Unlike the MIN/MAX and watershed fixtures, this one is **not** exact, and
//! `DIVERGENCES.md` D-004 records why: two conforming JPEG decoders may differ
//! because the standard fixes the DCT only to a stated accuracy, not bit for
//! bit. The tolerance below is on that difference, not on the reader's
//! geometry, which must be exact.

use std::path::{Path, PathBuf};

use qupath_slide::Slide;

/// Largest per-channel difference tolerated against QuPath's decode.
///
/// Justified by measurement, not chosen: the assertions below report the worst
/// difference actually seen, and it must stay well inside this.
const MAX_CHANNEL_DIFFERENCE: i32 = 4;

/// Largest tolerated mean absolute difference over a case.
///
/// A systematic colour-space error — the failure mode this test exists for —
/// moves the mean, while honest IDCT rounding does not.
const MAX_MEAN_DIFFERENCE: f64 = 0.75;

struct Case {
    name: String,
    level: usize,
    x: u32,
    y: u32,
    width: u32,
    height: u32,
    rgb: Vec<u8>,
}

fn fixture_path() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../parity/fixtures/SlideRegion.json")
}

fn slide_path(fixture: &str) -> PathBuf {
    let name = between(fixture, "\"slide\": \"", "\"");
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../data")
        .join(name)
}

fn between<'a>(haystack: &'a str, start: &str, end: &str) -> &'a str {
    let rest = &haystack[haystack.find(start).expect("start") + start.len()..];
    &rest[..rest.find(end).expect("end")]
}

fn number(block: &str, key: &str) -> u32 {
    let rest = &block[block.find(key).expect(key) + key.len()..];
    rest[..rest.find([',', '}']).expect("delimiter")]
        .trim()
        .parse()
        .expect("number")
}

fn parse(text: &str) -> Vec<Case> {
    let mut cases = Vec::new();
    for block in text.split("{\"name\": \"").skip(1) {
        let name = between(block, "", "\"").to_owned();
        if !block.contains("\"rgb\"") {
            continue;
        }
        cases.push(Case {
            name,
            level: number(block, "\"level\": ") as usize,
            x: number(block, "\"x\": "),
            y: number(block, "\"y\": "),
            width: number(block, "\"width\": "),
            height: number(block, "\"height\": "),
            rgb: between(block, "\"rgb\": [", "]")
                .split(',')
                .map(|v| v.trim().parse().expect("channel"))
                .collect(),
        });
    }
    cases
}

#[test]
fn matches_qupath_slide_pixels() {
    let fixture = fixture_path();
    let Ok(text) = std::fs::read_to_string(&fixture) else {
        // Slides are untracked because they are hundreds of megabytes, so this
        // test is skipped rather than failed where they are absent. It runs in
        // any checkout that has followed docs/test-data.md.
        qupath_testing::skipped(&format!("{} not recorded", fixture.display()));
        return;
    };

    let slide_path = slide_path(&text);
    if !slide_path.exists() {
        qupath_testing::skipped(&format!("{} not present", slide_path.display()));
        return;
    }

    let slide = Slide::open(&slide_path).expect("open slide");

    // Geometry must be exact. A reader that agrees on colour but disagrees on
    // where a level starts is not usable, and a tolerance would hide it.
    let expected_width = number(&text, "\"width\": ");
    let expected_height = number(&text, "\"height\": ");
    let expected_levels = number(&text, "\"levels\": ") as usize;
    assert_eq!(slide.levels()[0].width, expected_width, "level 0 width");
    assert_eq!(slide.levels()[0].height, expected_height, "level 0 height");
    assert_eq!(slide.levels().len(), expected_levels, "level count");

    let cases = parse(&text);
    assert!(!cases.is_empty(), "fixture parsed to no pixel cases");

    for case in &cases {
        let actual = slide
            .read_region_rgb(case.level, case.x, case.y, case.width, case.height)
            .unwrap_or_else(|e| panic!("{}: {e}", case.name));

        assert_eq!(
            actual.len(),
            case.rgb.len(),
            "{}: read {} bytes, QuPath gave {}",
            case.name,
            actual.len(),
            case.rgb.len()
        );

        let mut worst = 0i32;
        let mut worst_at = 0usize;
        let mut total = 0i64;
        for (index, (&mine, &theirs)) in actual.iter().zip(&case.rgb).enumerate() {
            let difference = (i32::from(mine) - i32::from(theirs)).abs();
            total += i64::from(difference);
            if difference > worst {
                worst = difference;
                worst_at = index;
            }
        }
        let mean = total as f64 / actual.len() as f64;

        assert!(
            worst <= MAX_CHANNEL_DIFFERENCE,
            "{}: worst channel difference {worst} at byte {worst_at} \
             (pixel {}, channel {}); mine {}, QuPath {}",
            case.name,
            worst_at / 3,
            worst_at % 3,
            actual[worst_at],
            case.rgb[worst_at]
        );
        assert!(
            mean <= MAX_MEAN_DIFFERENCE,
            "{}: mean absolute difference {mean:.3} exceeds {MAX_MEAN_DIFFERENCE}; \
             that is a systematic difference, not decoder rounding",
            case.name
        );

        println!(
            "{:>14}  level {}  {}x{}  worst {worst}  mean {mean:.3}",
            case.name, case.level, case.width, case.height
        );
    }
}
